inline QJsonObject native_mapping_source_state(const blender::bNodeTree &tree){
 using namespace blender;QJsonArray nodes,links;
 for(const auto &node:tree.nodes){QJsonArray inputs;for(const auto &socket:node.inputs){QJsonArray value;if(socket.type==SOCK_VECTOR&&socket.default_value){const auto *v=static_cast<const blender::bNodeSocketValueVector *>(socket.default_value)->value;for(int c=0;c<3;++c)value.append(v[c]);}else if(socket.type==SOCK_FLOAT&&socket.default_value)value.append(static_cast<const blender::bNodeSocketValueFloat *>(socket.default_value)->value);inputs.append(QJsonObject{{"id",socket.identifier},{"flag",int(socket.flag)},{"value",value}});}QJsonArray outputs;for(const auto &socket:node.outputs)outputs.append(QJsonObject{{"id",socket.identifier},{"flag",int(socket.flag)}});nodes.append(QJsonObject{{"name",node.name},{"flag",int(node.flag)},{"outputs",outputs},{"type",node.idname},{"mode",node.custom1},{"custom2",node.custom2},{"inputs",inputs}});}
 for(const auto &link:tree.links)links.append(QJsonArray{QString(link.fromnode->name),QString(link.fromsock->identifier),QString(link.tonode->name),QString(link.tosock->identifier),int(link.flag)});
 return {{"nodes",nodes},{"links",links}};
}
